// Process each language
for (const [lang, trans] of Object.entries(translations)) {
  const filePath = path.join(dir, `${lang}.json`);
  let content = fs.readFileSync(filePath, 'utf-8');
  
  // Replace each English key with the real translation
  for (const [key, value] of Object.entries(trans)) {
    const escapedKey = key.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    // Match the key with any value (English placeholder) and replace with our translation
    const regex = new RegExp(`("${escapedKey}"\\s*:\\s*)"[^"]*"`, 'g');
    const before = content;
    content = content.replace(regex, `$1"${value}"`);
    if (content === before) {
      // If key wasn't found with a simple string value, try another pattern
      const regex2 = new RegExp(`"${escapedKey}"\\s*:\\s*"[^"]*"`, 'g');
      if (!regex2.test(content)) {
        console.log(`  ⚠ ${lang}: key "${key}" not found`);
      }
    }
  }
  
  fs.writeFileSync(filePath, content);
  console.log(`✓ Updated ${lang}.json (${Object.keys(trans).length} keys)`);
}

console.log('\nAll done!');